const C={stone:'#d5c7a7',stoneDark:'#a69b85',brick:'#a5634e',brickDark:'#784c42',cream:'#e6d7bb',slate:'#485c63',roof:'#59666a',timber:'#55473d',oak:'#8a6748',iron:'#35534d',glass:'#759399',dark:'#35474d',red:'#994d43',white:'#e8e0ce'};
export const subtract=(a,b)=>a.map((v,i)=>v-b[i]);
export const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0);
export const normal=p=>{const n=cross(subtract(p[1],p[0]),subtract(p[2],p[0])),d=Math.hypot(...n);if(!(d>1e-12))throw Error('D090 degenerate face');return n.map(x=>x/d);};
