 bearingStorey(name,inner,outer,wallTop,top,color){this.part(name);const [x0,x1,z0,z1]=inner,[X0,X1,Z0,Z1]=outer,lo=[[x0,0,z0],[x1,0,z0],[x1,0,z1],[x0,0,z1]],waist=lo.map(([x,y,z])=>[x,wallTop,z]),hi=[[X0,top,Z0],[X1,top,Z0],[X1,top,Z1],[X0,top,Z1]];this.face(lo,[0,-1,0],color);this.face(hi,[0,1,0],color);for(let i=0;i<4;i++){const j=(i+1)%4,away=[(lo[i][0]+lo[j][0])/2-(x0+x1)/2,0,(lo[i][2]+lo[j][2])/2-(z0+z1)/2];this.face([lo[i],lo[j],waist[j],waist[i]],away,color);this.face([waist[i],waist[j],hi[j],hi[i]],[away[0],-.1,away[2]],color);}return this;}
 taperedCapital(name,x,z,y0,y1,lx,lz,hx,hz,color){this.part(name);const lo=[[x-lx,y0,z-lz],[x+lx,y0,z-lz],[x+lx,y0,z+lz],[x-lx,y0,z+lz]],hi=[[x-hx,y1,z-hz],[x+hx,y1,z-hz],[x+hx,y1,z+hz],[x-hx,y1,z+hz]];this.face(lo,[0,-1,0],color);this.face(hi,[0,1,0],color);for(let i=0;i<4;i++){const j=(i+1)%4;this.face([lo[i],lo[j],hi[j],hi[i]],[(lo[i][0]+lo[j][0])/2-x,-.01,(lo[i][2]+lo[j][2])/2-z],color);}return this;}
 footprintPrism(name,ring,y0,y1,color){this.part(name);const lo=ring.map(([x,z])=>[x,y0,z]),hi=ring.map(([x,z])=>[x,y1,z]);this.face(lo,[0,-1,0],color);this.face(hi,[0,1,0],color);for(let i=0;i<ring.length;i++){const j=(i+1)%ring.length,dx=ring[j][0]-ring[i][0],dz=ring[j][1]-ring[i][1];this.face([lo[i],lo[j],hi[j],hi[i]],[dz,0,-dx],color);}return this;}
 stoneStairFlight(name,x0,x1,z0,going,total,count,cap,lap,wall,finish){this.part(name);const end=z0+going*count+lap;this.face([[x0,0,z0],[x1,0,z0],[x1,0,end],[x0,0,end]],[0,-1,0],wall);for(let i=0;i<count;i++){const back=z0+i*going,front=z0+(i+1)*going+(i===count-1?lap:0),base=total*(i+1)/count,top=base+cap,previous=i?total*i/count+cap:0;for(const[x,n]of [[x0,-1],[x1,1]]){this.face([[x,0,back],[x,0,front],[x,base,front],[x,base,back]],[n,0,0],wall);this.face([[x,base,back],[x,base,front],[x,top,front],[x,top,back]],[n,0,0],finish);}this.face([[x0,top,back],[x1,top,back],[x1,top,front],[x0,top,front]],[0,1,0],finish);this.face([[x0,previous,back],[x1,previous,back],[x1,base,back],[x0,base,back]],[0,0,-1],wall);this.face([[x0,base,back],[x1,base,back],[x1,top,back],[x0,top,back]],[0,0,-1],finish);}this.face([[x0,0,end],[x1,0,end],[x1,total,end],[x0,total,end]],[0,0,1],wall);this.face([[x0,total,end],[x1,total,end],[x1,total+cap,end],[x0,total+cap,end]],[0,0,1],finish);return this;}
 box(name,x0,x1,z0,z1,y0,y1,color,solid=true){return this.profile(name,[[x0,y0],[x1,y0],[x1,y1],[x0,y1]],z0,z1,color,color,solid);}
 profile(name,profile,z0,z1,wall,roof,solid=true){this.part(name,solid);const mid=profile.reduce((s,p)=>[s[0]+p[0]/profile.length,s[1]+p[1]/profile.length],[0,0]),lo=profile.map(([x,y])=>[x,y,z0]),hi=profile.map(([x,y])=>[x,y,z1]);this.face(lo,[0,0,-1],wall);this.face(hi,[0,0,1],wall);for(let i=0;i<profile.length;i++){const j=(i+1)%profile.length,a=profile[i],b=profile[j],away=[b[1]-a[1],a[0]-b[0],0];this.face([lo[i],lo[j],hi[j],hi[i]],away,away[1]>0?roof:wall);}return this;}
 gable(name,x0,x1,z0,z1,y0,eave,ridge,wall=C.brick,roof=C.slate){return this.profile(name,[[x0,y0],[x1,y0],[x1,eave],[(x0+x1)/2,ridge],[x0,eave]],z0,z1,wall,roof);}
 barrel(name,x0,x1,z0,z1,y0,eave,rise,wall=C.brick,roof=C.slate){const p=[[x0,y0],[x1,y0]];for(let i=0;i<=8;i++){const a=i*Math.PI/8;p.push([(x0+x1)/2+(x1-x0)/2*Math.cos(a),eave+rise*Math.sin(a)]);}return this.profile(name,p,z0,z1,wall,roof);}
 hip(name,x0,x1,z0,z1,y0,eave,ridge,wall=C.stone,roof=C.slate){this.part(name);const lo=[[x0,y0,z0],[x1,y0,z0],[x1,y0,z1],[x0,y0,z1]],hi=lo.map(([x,y,z])=>[x,eave,z]),inset=Math.min(x1-x0,z1-z0)*.32,a=[(x0+x1)/2,ridge,z0+inset],b=[(x0+x1)/2,ridge,z1-inset];for(let i=0;i<4;i++){const j=(i+1)%4;this.face([lo[i],lo[j],hi[j],hi[i]],[(lo[i][0]+lo[j][0])/2-(x0+x1)/2,0,(lo[i][2]+lo[j][2])/2-(z0+z1)/2],wall);}this.face(lo,[0,-1,0],wall);this.face([hi[0],hi[1],a],[0,1,-1],roof);this.face([hi[1],hi[2],b,a],[1,1,0],roof);this.face([hi[2],hi[3],b],[0,1,1],roof);this.face([hi[3],hi[0],a,b],[-1,1,0],roof);return this;}
 pyramid(name,ring,y0,eave,ridge,wall=C.stone,roof=C.slate){this.part(name);const cx=ring.reduce((s,a)=>s+a[0],0)/ring.length,cz=ring.reduce((s,a)=>s+a[1],0)/ring.length,lo=ring.map(([x,z])=>[x,y0,z]),hi=ring.map(([x,z])=>[x,eave,z]);this.face(lo,[0,-1,0],wall);for(let i=0;i<ring.length;i++){const j=(i+1)%ring.length,away=[(ring[i][0]+ring[j][0])/2-cx,0,(ring[i][1]+ring[j][1])/2-cz];if(eave>y0)this.face([lo[i],lo[j],hi[j],hi[i]],away,wall);this.face([hi[i],hi[j],[cx,ridge,cz]],[away[0],1,away[2]],roof);}return this;}
 transform(from,cx,cz,angle){return this.transformBasis(from,cx,cz,Math.cos(angle),Math.sin(angle));}
 transformBasis(from,cx,cz,c,s){const f=([x,y,z])=>[cx+x*c+z*s,y,cz-x*s+z*c];for(const p of this.parts.slice(from)){for(const face of p.faces)face.points=face.points.map(f);}const start=this.parts[from]?.start??this.triangles.length;for(const t of this.triangles.slice(start)){t.p=t.p.map(f);t.n=normal(t.p);}return this;}
 panel(name,x0,x1,z,y0,y1,color,back=false){this.part(name,false).face([[x0,y0,z],[x1,y0,z],[x1,y1,z],[x0,y1,z]],[0,0,back?-1:1],color);return this;}
