 door(x,z,y,w,h,color=C.iron){this.panel('door-reveal',x-w/2-.015,x+w/2+.015,z,y,y+h+.02,C.stone);this.panel('entry-door',x-w/2,x+w/2,z+.001,y,y+h,color);this.panel('door-leaf-joint',x-.002,x+.002,z+.002,y,y+h,C.dark);return this;}
 sideWindows(x,z0,z1,y,w,h,count,left=false,cols=2,rows=2){for(let i=0;i<count;i++){const start=this.parts.length;this.window(0,0,y,w,h,cols,rows);this.transformBasis(start,x,z0+(z1-z0)*(i+.5)/count,0,left?-1:1);}return this;}
 chimney(x,z,y0,y1){this.box('chimney',x-.026,x+.026,z-.027,z+.027,y0,y1,C.brickDark);this.box('chimney-coping',x-.035,x+.035,z-.035,z+.035,y1-.025,y1,C.cream,false);return this;}

 halfHip(name,x0,x1,z0,z1,eave,end,ridge,inset,wall,roof){this.part(name);const mid=(x0+x1)/2,A=[mid,end,z0],B=[mid,end,z1],R=[mid,ridge,z0+inset],S=[mid,ridge,z1-inset],a=[x0,eave,z0],b=[x1,eave,z0],c=[x1,eave,z1],d=[x0,eave,z1];this.face([[x0,0,z0],[x1,0,z0],b,A,a],[0,0,-1],wall);this.face([[x0,0,z1],[x1,0,z1],c,B,d],[0,0,1],wall);this.face([[x0,0,z0],[x0,0,z1],d,a],[-1,0,0],wall);this.face([[x1,0,z0],[x1,0,z1],c,b],[1,0,0],wall);this.face([[x0,0,z0],[x1,0,z0],[x1,0,z1],[x0,0,z1]],[0,-1,0],wall);for(const [p,n]of [[[a,A,R],[-1,1,-1]],[[b,A,R],[1,1,-1]],[[d,B,S],[-1,1,1]],[[c,B,S],[1,1,1]],[[a,R,S,d],[-1,1,0]],[[b,R,S,c],[1,1,0]]])this.face(p,n,roof);return this;}
 ramp(name,x0,x1,z0,z1,height,color){const start=this.parts.length;this.profile(name,[[z0,0],[z1,0],[z0,height]],-x1,-x0,color,color);this.transformBasis(start,0,0,0,-1);return this;}
