const U=[[1,0],[.9238795325112867,.3826834323650898],[.7071067811865476,.7071067811865476],[.3826834323650898,.9238795325112867],[0,1],[-.3826834323650898,.9238795325112867],[-.7071067811865476,.7071067811865476],[-.9238795325112867,.3826834323650898],[-1,0],[-.9238795325112867,-.3826834323650898],[-.7071067811865476,-.7071067811865476],[-.3826834323650898,-.9238795325112867],[0,-1],[.3826834323650898,-.9238795325112867],[.7071067811865476,-.7071067811865476],[.9238795325112867,-.3826834323650898]];
const ccw=ps=>ps.reduce((s,p,i)=>s+p[0]*ps[(i+1)%ps.length][1]-p[1]*ps[(i+1)%ps.length][0],0)>0?ps:[...ps].reverse();
function gableX(b,name,x0,x1,z0,z1,eave,ridge,wall=C.brick,roof=C.slate){const from=b.parts.length;b.gable(name,z0,z1,-x1,-x0,0,eave,ridge,wall,roof);b.transformBasis(from,0,0,0,-1);}
function barrel(b,name,x0,x1,z0,z1,eave,rise,wall=C.brick,roof=C.slate){b.profile(name,[[x0,0],[x1,0],...U.slice(0,9).map(([x,y])=>[(x0+x1)/2+(x1-x0)/2*x,eave+rise*y])],z0,z1,wall,roof);}
function barrelX(b,name,x0,x1,z0,z1,eave,rise,wall=C.brick,roof=C.slate){const from=b.parts.length;barrel(b,name,z0,z1,-x1,-x0,eave,rise,wall,roof);b.transformBasis(from,0,0,0,-1);}
function alongGable(b,name,a,c,width,eave,ridge,wall=C.brick){const dx=c[0]-a[0],dz=c[1]-a[1],length=Math.hypot(dx,dz),from=b.parts.length;b.gable(name,-width/2,width/2,0,length,0,eave,ridge,wall,C.slate);b.transformBasis(from,a[0],a[1],dz/length,dx/length);}
// One closed polygonal body with a two-ended ridge; not an oval drum/dome.
function ridgePolygon(b,name,ring,eave,A,B,wall=C.brick,roof=C.slate,along='x'){ring=ccw(ring);const lo=ring.map(([x,z])=>[x,0,z]),hi=ring.map(([x,z])=>[x,eave,z]),axis=along==='x'?0:2,split=(A[axis]+B[axis])/2;b.part(name).face(lo,[0,-1,0],wall);for(let i=0;i<ring.length;i++){const j=(i+1)%ring.length,d=[ring[j][1]-ring[i][1],0,ring[i][0]-ring[j][0]];b.face([lo[i],lo[j],hi[j],hi[i]],d,wall);const P=hi[i][axis]<=split?A:B,Q=hi[j][axis]<=split?A:B;b.face([hi[i],hi[j],Q],[d[0],1,d[2]],roof);if(P!==Q)b.face([hi[i],Q,P],[0,1,0],roof);}return b;}
function crop(b,name,x0,x1,z0,z1){b.box(name,x0,x1,z0,z1,0,.008,'#738258');}

// Ring lofts are one closed ground-supported solid, never stacked roof plates.
function loft(b,name,rings,wall=C.stone,roof=C.slate){b.part(name);const cx=rings[0].reduce((s,p)=>s+p[0]/rings[0].length,0),cz=rings[0].reduce((s,p)=>s+p[2]/rings[0].length,0);b.face(rings[0],[0,-1,0],wall);b.face(rings.at(-1),[0,1,0],roof);for(let k=0;k<rings.length-1;k++)for(let i=0;i<rings[k].length;i++){const j=(i+1)%rings[k].length,a=rings[k],c=rings[k+1],rad=p=>Math.hypot(p[0]-cx,p[2]-cz),n=[(a[i][0]+a[j][0]+c[i][0]+c[j][0])/4-cx,(rad(a[i])+rad(a[j])-rad(c[i])-rad(c[j]))/2,(a[i][2]+a[j][2]+c[i][2]+c[j][2])/4-cz];b.face([a[i],a[j],c[j],c[i]],n,Math.abs(a[i][1]-c[i][1])<1e-12?roof:wall);}return b;}
const rect=(x0,x1,z0,z1,y)=>[[x0,y,z0],[x1,y,z0],[x1,y,z1],[x0,y,z1]],circle=(cx,cz,r,y)=>U.map(([x,z])=>[cx+r*x,y,cz+r*z]);
function circularBody(b,name,cx,cz,levels,wall=C.stone,roof=C.slate){const last=levels.at(-1);if(last[0]!==0)return loft(b,name,levels.map(([r,y])=>circle(cx,cz,r,y)),wall,roof);const rings=levels.slice(0,-1).map(([r,y])=>circle(cx,cz,r,y));b.part(name).face(rings[0],[0,-1,0],wall);for(let k=0;k<rings.length-1;k++)for(let i=0;i<16;i++){const j=(i+1)%16,a=rings[k],c=rings[k+1];b.face([a[i],a[j],c[j],c[i]],[(a[i][0]+a[j][0])/2-cx,levels[k][0]-levels[k+1][0],(a[i][2]+a[j][2])/2-cz],wall);}const top=rings.at(-1);for(let i=0;i<16;i++)b.face([top[i],top[(i+1)%16],[cx,last[1],cz]],[0,1,0],roof);return b;}
function roofField(b,name,ring,height,wall=C.stone,roof=C.slate,center=null){ring=ccw(ring);const lo=ring.map(([x,z])=>[x,0,z]),hi=ring.map(([x,z])=>[x,height(x,z),z]);b.part(name).face(lo,[0,-1,0],wall);for(let i=0;i<ring.length;i++){const j=(i+1)%ring.length;b.face([lo[i],lo[j],hi[j],hi[i]],[ring[j][1]-ring[i][1],0,ring[i][0]-ring[j][0]],wall);}if(center){const[x,z]=center,P=[x,height(x,z),z];for(let i=0;i<ring.length;i++)b.face([hi[i],hi[(i+1)%ring.length],P],[0,1,0],roof);}else b.face(hi,[0,1,0],roof);return b;}
function castle(){const b=new Architecture('castellated-tank-water-tower');loft(b,'battered-enclosed-reservoir-shaft',[rect(.20,.80,.20,.80,0),rect(.28,.72,.28,.72,.35),rect(.28,.72,.28,.72,1.35)],C.stone,C.roof);for(const[x,z]of [[.25,.25],[.75,.25],[.25,.75],[.75,.75]])loft(b,'grounded-corner-buttress-'+x+'-'+z,[rect(x-.075,x+.075,z-.075,z+.075,0),rect(x-.04,x+.04,z-.04,z+.04,1.30)],C.stoneDark,C.stone);const top=[[.26,1.46],[.36,1.46],[.36,1.39],[.45,1.39],[.45,1.46],[.55,1.46],[.55,1.39],[.64,1.39],[.64,1.46],[.74,1.46]],p=[[.26,0],[.74,0],...[...top].reverse()];for(const[name,z0,z1]of [['north',.26,.30],['south',.70,.74]])b.profile(name+'-integral-crenellated-wall',p,z0,z1,C.stone,C.stone);const side=[[.29,0],[.71,0],[.71,1.44],[.63,1.44],[.63,1.38],[.55,1.38],[.55,1.44],[.45,1.44],[.45,1.38],[.37,1.38],[.37,1.44],[.29,1.44]];for(const[name,x0,x1]of [['west',.27,.31],['east',.69,.73]]){const k=b.parts.length;b.profile(name+'-integral-crenellated-wall',side,-x1,-x0,C.stone,C.stone);b.transformBasis(k,0,0,0,-1);}b.hip('grounded-front-valve-vestibule',.39,.61,.68,.84,0,.32,.37,C.stone,C.roof);castleDetails(b);return b.finish();}
